import{_ as o,o as t,c as s,a0 as a}from"./chunks/framework.BGyYNsHo.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/01-architecture.md","filePath":"explanation/01-architecture.md"}'),d={name:"explanation/01-architecture.md"};function n(c,e,i,r,l,p){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>An architectural overview of LocalSWMM: its client-side structure, module dependencies, global state management, and end-to-end simulation data pipeline.</p><h2 id="core-architectural-decisions" tabindex="-1">Core Architectural Decisions <a class="header-anchor" href="#core-architectural-decisions" aria-label="Permalink to &quot;Core Architectural Decisions&quot;">​</a></h2><p>LocalSWMM is designed from the ground up to execute all hydraulic modeling tasks directly inside the user&#39;s browser without reliance on a server-side computing backend.</p><ul><li><strong>No backend required:</strong> The Python server (<code>server.py</code>) is merely a local static file server and health endpoint (<code>GET /api/status</code>).</li><li><strong>Dependency-free UI:</strong> Built with ~15,000 lines of standard JavaScript structured via IIFEs, with Mapbox GL JS providing interactive map rendering.</li><li><strong>WASM-embedded hydraulics:</strong> The OpenSWMM engine is cross-compiled for <code>wasm32-emscripten</code> with C++ dependencies (Eigen, HDF5, nlohmann-json, SUNDIALS), executing inside a dedicated Web Worker (<code>simWorker.js</code>).</li></ul><h2 id="architecture-at-a-glance" tabindex="-1">Architecture at a glance <a class="header-anchor" href="#architecture-at-a-glance" aria-label="Permalink to &quot;Architecture at a glance&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        ┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>                        │                       BROWSER                          │</span></span>
<span class="line"><span>                        │                                                        │</span></span>
<span class="line"><span>  ┌────────────┐        │   ┌───────────────────────  index.html  ────────────┐  │</span></span>
<span class="line"><span>  │  server.py │───────▶│   │  [classic &lt;script&gt; modules, ordered by deps]     │  │</span></span>
<span class="line"><span>  │  static    │        │   └───────────────┬──────────────────────────────────┘  │</span></span>
<span class="line"><span>  │  :8080     │        │                   │                                    │</span></span>
<span class="line"><span>  └────────────┘        │                   ▼                                    │</span></span>
<span class="line"><span>                        │   ┌───────────────────────────────┐                    │</span></span>
<span class="line"><span>                        │   │  UI layer (ui.js)             │                    │</span></span>
<span class="line"><span>                        │   │  Map (app.js)  Tools          │                    │</span></span>
<span class="line"><span>                        │   │  Network store (network.js)   │                    │</span></span>
<span class="line"><span>                        │   └───────┬───────────────┬───────┘                    │</span></span>
<span class="line"><span>                        │           │               │                            │</span></span>
<span class="line"><span>                        │           ▼               ▼                            │</span></span>
<span class="line"><span>                        │   ┌──────────────────────┐                             │</span></span>
<span class="line"><span>                        │   │ INP serialize        │                             │</span></span>
<span class="line"><span>                        │   │ (inpExporter.js)     │                             │</span></span>
<span class="line"><span>                        │   │ INP parse            │                             │</span></span>
<span class="line"><span>                        │   │ (inpParser.js)       │                             │</span></span>
<span class="line"><span>                        │   └──────────┬───────────┘                             │</span></span>
<span class="line"><span>                        │              │                                         │</span></span>
<span class="line"><span>                        │              ▼                                         │</span></span>
<span class="line"><span>                        │   ┌─────────────────┐                                  │</span></span>
<span class="line"><span>                        │   │  simWorker.js   │ (Web Worker)                     │</span></span>
<span class="line"><span>                        │   └───────┬─────────┘                                  │</span></span>
<span class="line"><span>                        │           │                                            │</span></span>
<span class="line"><span>                        │           ▼                                            │</span></span>
<span class="line"><span>                        │   ┌─────────────────────────────────────────────┐      │</span></span>
<span class="line"><span>                        │   │   Emscripten WASM:  swmm6wasm.js/.wasm       │      │</span></span>
<span class="line"><span>                        │   │   ──────────────────────────────────────     │      │</span></span>
<span class="line"><span>                        │   │   OpenSWMM engine (C++20, static lib)        │      │</span></span>
<span class="line"><span>                        │   │   exported C API: swmm_engine_*              │      │</span></span>
<span class="line"><span>                        │   └─────────────────────────────────────────────┘      │</span></span>
<span class="line"><span>                        └─────────────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>Data flow (simulation):</strong> model (<code>Net</code>) → <code>inpExporter.generateInp()</code> → <code>.inp</code> string → Worker (<code>simWorker.js</code>) → <code>FS.writeFile(&#39;/in.inp&#39;)</code> → <code>swmm_engine_open/initialize/start</code> → <code>stride()</code> loop → <code>.rpt</code> + <code>.out</code> read back → <code>swmmOutParser</code> → <code>results.js</code> rendering (tables, map colors, time slider, profile/chart plots).</p><h2 id="module-system-and-globals" tabindex="-1">Module system and globals <a class="header-anchor" href="#module-system-and-globals" aria-label="Permalink to &quot;Module system and globals&quot;">​</a></h2><p>There are <strong>no ES modules, no bundler, no <code>import</code>/<code>export</code></strong>. Every file is a classic script wrapped in an IIFE. Modules communicate exclusively through globals attached to <code>window</code>. <strong>Script order in <code>index.html</code> is the dependency contract</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config.js → mapbox/proj4/shp/dxf/geotiff (CDN)</span></span>
<span class="line"><span>→ inpParser → inpExporter → network → swmmOutParser → street_view_overlay</span></span>
<span class="line"><span>→ swmm6wasm → results → importers → app → tools → profile → plot</span></span>
<span class="line"><span>→ landcover → curves → lid → quality → aquifer → snowpack → ui</span></span>
<span class="line"><span>(ui.js LAST — it wires every button)</span></span></code></pre></div><p>The principal global singletons:</p><table tabindex="0"><thead><tr><th>Global</th><th>Owner of</th><th>Defined at</th></tr></thead><tbody><tr><td><code>window.map</code></td><td>Mapbox GL <code>Map</code> instance</td><td><code>app.js</code></td></tr><tr><td><code>window.App</code></td><td>UI/app state (<code>currentStyle</code>, visibility flags, <code>selection</code> Set, <code>lastRunReport</code>, <code>outData</code>, …)</td><td><code>app.js</code></td></tr><tr><td><code>window.Net</code></td><td><code>Network</code> class instance — <strong>single source of truth</strong> for all model data + undo/redo + autosave</td><td><code>network.js</code></td></tr><tr><td><code>window.Tools</code></td><td>Tool state machine (selection, drawing, hit-testing, drag)</td><td><code>tools.js</code></td></tr><tr><td><code>window.ResultStyling</code></td><td>Simulation result coloring engine</td><td><code>results.js</code></td></tr><tr><td><code>window.AnimationUI</code></td><td>Time-slider play/pause</td><td><code>ui.js</code></td></tr><tr><td><code>window.CONFIG</code></td><td>API keys</td><td><code>config.js</code></td></tr><tr><td><code>window.inpParser</code> / <code>window.inpExporter</code></td><td>INP parse / serialize</td><td><code>inpParser.js</code>, <code>inpExporter.js</code></td></tr><tr><td><code>window.SWMMOutParser</code></td><td><code>.out</code> binary parser</td><td><code>swmmOutParser.js</code></td></tr><tr><td>Module editors (lazy)</td><td><code>CurveEditor</code>, <code>LIDControls</code>, <code>QualityEditor</code>, <code>AquiferEditor</code>, <code>SnowpackEditor</code>, <code>TimeSeriesPlot</code>, <code>ProfilePlot</code>, <code>StreetViewOverlay</code>, <code>Importers</code></td><td>—</td></tr></tbody></table><p>Consequences of this design:</p><ul><li><strong>State is shared by convention.</strong> <code>tools.js</code> and <code>ui.js</code> capture <code>window.map</code>/<code>window.App</code> at load time, so <code>ui.js</code> must load after <code>app.js</code>.</li><li><strong>Adding a module</strong> means adding a <code>&lt;script&gt;</code> tag in the right position in <code>index.html</code> and exposing globals; there is no import graph the tooling can validate.</li><li><strong>Rendering is two-track:</strong> <code>Net</code> owns geometry + undo + persistence (data); <code>App</code> + Mapbox own view state. Mapbox <strong>feature-state</strong> (<code>selected</code>, <code>hovered</code>, <code>resultColor</code>) is the bridge between them.</li></ul><h2 id="ui-shell-—-index-html" tabindex="-1">UI shell — <code>index.html</code> <a class="header-anchor" href="#ui-shell-—-index-html" aria-label="Permalink to &quot;UI shell — \`index.html\`&quot;">​</a></h2><p>The whole app is a CSS grid <code>#app-grid</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grid-template-areas:</span></span>
<span class="line"><span>  &quot;toolbar toolbar toolbar&quot;</span></span>
<span class="line"><span>  &quot;palette map     panel&quot;</span></span>
<span class="line"><span>  &quot;status  status  status&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Container</th><th>ID</th><th>Contents</th></tr></thead><tbody><tr><td>Toolbar</td><td><code>#toolbar</code></td><td>Undo/Redo · Save/Load(dropdown)/Export-INP · Options · TS-plot · <strong>Run</strong> · Clear · Data-menu (Curves/LID/Quality/Aquifer/Snowpack)</td></tr><tr><td>Left palette</td><td><code>#tool-palette</code></td><td><code>[select] [delete]</code> + Node tools (junction, outfall, storage, divider) + Link tools (conduit, pump, weir, orifice) + Area tools (subcatchment, raingage)</td></tr><tr><td>Map area</td><td><code>#map-container</code></td><td><code>#map</code>, OSM search, map-settings card (basemap / layer toggles / units / DEM source / Sample-DEM-all), Street View pegman, time-slider panel, profile modal, TS modals</td></tr><tr><td>Right panel</td><td><code>#panel-right</code></td><td>Resizable; tabs <strong>Properties / Results / Report</strong> (<code>#tab-props</code>, <code>#tab-results</code>, <code>#tab-report</code>)</td></tr><tr><td>Status bar</td><td><code>#statusbar</code></td><td><code>#sb-tool</code>, <code>#sb-nodes</code>, <code>#sb-links</code>, <code>#sb-subcatchments</code>, <code>#sb-gages</code>, <code>#sb-coords</code></td></tr><tr><td>Modals</td><td><code>.modal-overlay</code>+<code>.modal-box</code></td><td>Options, Projection, Import-As, Run-Status (+minimized badge)</td></tr></tbody></table><h2 id="ui-framework" tabindex="-1">UI framework <a class="header-anchor" href="#ui-framework" aria-label="Permalink to &quot;UI framework&quot;">​</a></h2><p><strong>Hand-rolled, dependency-free.</strong> Dynamic content is DOM-string + <code>innerHTML</code> (e.g. the properties panel <code>renderPropsPanel</code>); all wiring is <code>addEventListener</code>. Recurring component classes live in <code>styles.css</code>:</p><ul><li><code>.tb-btn</code>, <code>.tb-btn-run</code>, <code>.tb-icon-btn</code>, <code>.tb-dropdown</code>(+<code>.open</code>), <code>.tb-pill</code>(+<code>.active</code>)</li><li><code>.tool-btn</code>(+<code>.active</code>, <code>.tool-btn-danger</code>), <code>.tool-divider</code>, <code>.tool-group-label</code></li><li><code>.side-panel</code>, <code>.panel-tabs</code>, <code>.panel-tab</code>(+<code>.active</code>), <code>.tab-badge</code></li><li><code>.modal-overlay</code>, <code>.modal-box</code>, <code>.modal-actions</code></li><li><code>.prop-section-title</code>, <code>.prop-row</code>, <code>.prop-actions</code></li></ul><p><strong>Theming</strong> uses CSS variables: <code>--accent</code>, <code>--danger</code>, <code>--bg-panel</code>, layout vars <code>--toolbar-h:44px</code>, <code>--statusbar-h:26px</code>, <code>--panel-w:280px</code>, <code>--palette-w:46px</code>. <code>--panel-w</code> is updated at runtime during resize.</p><p><strong>No i18n.</strong> All strings are hardcoded English. The only &quot;localization&quot; is unit formatting via <code>const U = (si, us) =&gt; Net.units === &#39;US&#39; ? us : si;</code> used by the schema-driven property forms (<code>FIELD_DEFS</code>).</p><h2 id="tool-system-—-tools-js" tabindex="-1">Tool system — <code>tools.js</code> <a class="header-anchor" href="#tool-system-—-tools-js" aria-label="Permalink to &quot;Tool system — \`tools.js\`&quot;">​</a></h2><p>A single hand-rolled state machine (<code>window.Tools</code>):</p><ul><li>Tool registry maps palette <code>data-tool</code> names to types: <code>NODE_TOOL_TYPES</code> (<code>junction→JUNCTION</code>, <code>outfall→OUTFALL</code>, <code>storage→STORAGE</code>, <code>divider→DIVIDER</code>, <code>raingage→RAINGAGE</code>) and <code>LINK_TOOL_TYPES</code> (<code>conduit</code>, <code>pump</code>, <code>orifice</code>, <code>weir</code>, <code>outlet</code>), plus special modes <code>select</code>, <code>subcatchment</code>, <code>delete</code>.</li><li><strong><code>Tools.setTool(name)</code></strong> cancels drawing, toggles palette highlight, updates <code>#sb-tool</code>, switches the map cursor, and disables <code>map.doubleClickZoom</code> in subcatchment mode.</li><li><strong>Drawing state:</strong> <code>linkFrom</code> (first endpoint), <code>linkVertices[]</code>, <code>polyVertices[]</code>, <code>dragging</code>.</li><li><strong>Hit-testing:</strong> <code>featureAt(point)</code> ranks nodes &gt; links &gt; subcatchments in a 12 px box; <code>snapNodeAt</code> uses a 24 px box over <code>swmm-nodes-layer</code>, skipping rain gages for hydraulic ops.</li><li><strong>All map interactions dispatch through one <code>map.on(&#39;click&#39;)</code> handler</strong> that switches on <code>Tools.active</code>: node placement, link drawing (first click must land on a node; subsequent clicks snap), subcatchment vertex push, delete, select. <code>dblclick</code> finishes a subcatchment. <code>mousemove</code> updates the ghost draft and the hover popup. <code>mousedown</code> drives node dragging, coalesced into a single undo step via <code>Net.commitMove()</code> on mouseup.</li><li><strong>Keyboard:</strong> <code>Esc</code> cancels/clears, <code>Ctrl+Z</code>/<code>Ctrl+Y</code>/<code>Ctrl+Shift+Z</code> undo-redo, <code>Ctrl+A</code> select all, <code>Del</code>/<code>Backspace</code> delete, <code>Enter</code> finishes a subcatchment.</li></ul><blockquote><p>Adding a new tool requires: an entry in <code>NODE_TOOL_TYPES</code>/<code>LINK_TOOL_TYPES</code>, a branch in the <code>click</code> handler, and a palette button.</p></blockquote><h2 id="state-persistence" tabindex="-1">State persistence <a class="header-anchor" href="#state-persistence" aria-label="Permalink to &quot;State persistence&quot;">​</a></h2><ul><li><strong>Autosave:</strong> every <code>Net.emit()</code> triggers <code>scheduleAutosave()</code>, a 2 s debounce that writes <code>JSON.stringify(serialize())</code> to <strong>localStorage</strong> key <code>openswmm3d.project</code>. If localStorage throws (quota), it falls back to <strong>IndexedDB</strong> (DB <code>openswmm3d</code>, store <code>kv</code>). Restore prefers localStorage, then IndexedDB, gated on ≥1 node/link.</li><li><strong>Save / Load:</strong> <code>Net.downloadProject()</code> produces a pretty-printed <code>*.oswmm.json</code>; load goes through <code>Net.loadState(data, true)</code>. JSON and GeoJSON files are both accepted (GeoJSON routes to the import/projection dialogs).</li><li><strong>Panel geometry</strong> is also persisted: right-panel width in <code>localStorage[&#39;panel-w&#39;]</code>.</li></ul>`,30)])])}const g=o(d,[["render",n]]);export{h as __pageData,g as default};
